class Solution {
public:
    int clumsy(int n) {
        vector<int> st;
        st.push_back(n);
        int op = 0;
        for (int i = n - 1; i >= 1; --i) {
            if (op == 0) {
                st.back() *= i;
            } else if (op == 1) {
                st.back() /= i;
            } else if (op == 2) {
                st.push_back(i);
            } else {
                st.push_back(-i);
            }
            op = (op + 1) % 4;
        }
        int sum = 0;
        for (int x : st) sum += x;
        return sum;
    }
};

class Solution {
    public int clumsy(int n) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(n);
        int op = 0;
        for (int i = n - 1; i >= 1; --i) {
            if (op == 0) {
                stack.push(stack.pop() * i);
            } else if (op == 1) {
                stack.push(stack.pop() / i);
            } else if (op == 2) {
                stack.push(i);
            } else {
                stack.push(-i);
            }
            op = (op + 1) % 4;
        }
        int sum = 0;
        for (int x : stack) sum += x;
        return sum;
    }
}

var clumsy = function(n) {
    const stack = [n];
    let op = 0;
    for (let i = n - 1; i >= 1; i--) {
        if (op === 0) {
            stack.push(stack.pop() * i);
        } else if (op === 1) {
            const top = stack.pop();
            stack.push(Math.trunc(top / i));
        } else if (op === 2) {
            stack.push(i);
        } else {
            stack.push(-i);
        }
        op = (op + 1) % 4;
    }
    return stack.reduce((a, b) => a + b, 0);
};
